-- Migración 003 — Catálogo real de fórmulas del motor de cálculo
-- ----------------------------------------------------------------------------
-- Carga las 159 fórmulas (FormulaTasa) y 985 acumuladores (FormulaTasaAcumuladores)
-- del sistema legacy en las tablas del módulo emisiones. Autocontenida (no depende
-- de los CSV). Idempotente: si ya hay >=100 fórmulas cargadas, no hace nada (no pisa
-- ediciones hechas por la UI).
--
-- Uso:
--   docker compose exec -T postgres sh -c 'psql -U "$POSTGRES_USER" -d "$POSTGRES_DB"' \
--     < migrations/003_catalogo_formulas.sql
-- Regenerar desde los CSV: python3 /tmp/gen_import_formulas.py
-- ----------------------------------------------------------------------------
DO $mig$
BEGIN
  IF (SELECT count(*) FROM emisiones_formula_tasa) >= 100 THEN
    RAISE NOTICE 'Catálogo de fórmulas ya cargado; se omite.';
    RETURN;
  END IF;
  DELETE FROM emisiones_formula_tasa_acumuladores;
  DELETE FROM emisiones_formula_tasa;
END $mig$;
